export function iconSvg(name) {
  return `<svg class="icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" data-lucide="${name}">${ICONS[name]}</svg>`;
}

// Replaces <span data-icon="name"></span> placeholders with inline SVG.
export function applyIcons(root = document) {
  for (const el of root.querySelectorAll("[data-icon]")) {
    const extra = [...el.classList].join(" ");
    el.outerHTML = iconSvg(el.dataset.icon).replace('class="icon"', `class="icon${extra ? " " + extra : ""}"`);
  }
}
